const rows = $input.all().map(i=>i.json);
const cutoff = Date.now() - 14*86400000;
const set = new Set();
for(const r of rows){ const tk = String(r.topic_key||'').trim(); if(!tk) continue; const d = r.reported_date ? Date.parse(r.reported_date) : NaN; if(!isNaN(d) && d < cutoff) continue; set.add(tk); }
const coveredTopics = Array.from(set).slice(0,60).join(', ');
return [{ json: { coveredTopics, coveredCount: set.size } }];

const rows = $input.all().map(i => i.json);
// Gewichtete Sortierung: inhaltlicher Score bleibt fuehrend, Trust-Score der Quelle als sekundaeres Signal
const weighted = rows.map(r => ({ ...r, _weighted: (r.score||0) + (((r.trust_score!=null?r.trust_score:5))/10)*2 }));
weighted.sort((a,b) => b._weighted - a._weighted);
const top = weighted.slice(0, 40);
const cand = top.map((r, idx) => ({ i: idx, url_hash: r.url_hash, url: r.url, title: r.title, source: r.source, score: r.score, category: r.category, region: r.region||'INT', trust_score: (r.trust_score!=null?r.trust_score:5), summary: String(r.summary||'').slice(0,300) }));
const payload = JSON.stringify(cand.map(c => ({ i: c.i, t: c.title, s: c.source, sc: c.score, cat: c.category, reg: c.region, tr: c.trust_score, sum: c.summary })));
const allHashes = rows.map(r => r.url_hash);
const coveredTopics = ($('Themen sammeln').first().json.coveredTopics) || '';
return [{ json: { count: cand.length, payload, cand, allHashes, coveredTopics } }];

