let raw = ($json && $json.text) ? $json.text : (($json && $json.output) ? $json.output : '');
let brief = {}; try { brief = JSON.parse(String(raw).replace(/```json/g,'').replace(/```/g,'').trim()); } catch(e){ brief = { main:[], apps:[], radar:[] }; }
const b = $('Kandidaten buendeln').first().json;
const cand = b.cand || []; const allHashes = b.allHashes || [];
const byI = {}; cand.forEach(c => { byI[c.i] = c; });
function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function sect(list, cap){ return (Array.isArray(list)?list:[]).slice(0,cap); }
const main = sect(brief.main,8), apps = sect(brief.apps,3), radar = sect(brief.radar,3);
const selected = []; const lines = [];
lines.push('<b>KI Daily \u00b7 ' + $now.toFormat('dd.LL.yyyy') + '</b>');
function render(title, list){ if(!list.length) return; lines.push(''); lines.push('<b>'+title+'</b>'); for(const it of list){ const c = byI[it.i]; if(!c) continue; const flag = it.strategic ? ' \u2691' : ''; lines.push('\u2022 <a href="'+esc(c.url)+'">'+esc(it.headline||c.title)+'</a>'+flag); if(it.why) lines.push('  <i>'+esc(it.why)+'</i>'); selected.push({ url_hash: c.url_hash, section: title, topic_key: it.topic_key||'', development_stage: it.development_stage||'', strategic: !!it.strategic }); } }
render('Wichtig', main); render('Tools & Apps', apps); render('Auf dem Radar', radar);
const telegram_html = lines.join('\n');
const selSet = new Set(selected.map(s => s.url_hash));
const archived = allHashes.filter(h => !selSet.has(h));
return [{ json: { telegram_html, selected, archived, reported_count: selected.length } }];

const brief = $('Brief bauen').first().json;
const sel = brief.selected || []; const arch = brief.archived || [];
const nowIso = $now.toISO();
const out = [];
for(const s of sel){ out.push({ json: { url_hash: s.url_hash, status: 'reported', reported: true, reported_date: nowIso, topic_key: s.topic_key || '', development_stage: s.development_stage || '' } }); }
for(const h of arch){ out.push({ json: { url_hash: h, status: 'archived', reported: false, reported_date: nowIso, topic_key: '', development_stage: '' } }); }
return out;

